class Average:
    def __init__(self):
        self.total = 0.0
        self.n = 0

    def add(self, value):
        self.total += value
        self.n += 1

    def mean(self):
        return self.total / self.n

files.test_stats.py:
import pytest

from stats import Average


def test_empty_raises():
    with pytest.raises(ValueError):
        Average().mean()


def test_simple_mean():
    a = Average()
    for v in (1, 2, 3, 4):
        a.add(v)
    assert a.mean() == 2.5


def test_precision():
    a = Average()
    for _ in range(1000):
        a.add(0.1)
    assert abs(a.mean() - 0.1) < 1e-12

files.test_config.py:
from config import merge_configs


def test_override_wins():
    assert merge_configs({'a': 1}, {'a': 2}) == {'a': 2}


def test_nested_merge():
    out = merge_configs({'db': {'host': 'x', 'port': 1}}, {'db': {'port': 2}})
    assert out == {'db': {'host': 'x', 'port': 2}}


def test_inputs_not_mutated():
    base = {'db': {'host': 'x'}}
    merge_configs(base, {'db': {'host': 'y'}})
    assert base == {'db': {'host': 'x'}}

