def truncate_words(text, n):
    words = text.split(' ')
    return ' '.join(words[:n]) + '…'

files.test_text.py:
from text import truncate_words


def test_truncates():
    assert truncate_words('one two three four', 2) == 'one two…'


def test_no_ellipsis_when_short():
    assert truncate_words('one two', 5) == 'one two'


def test_handles_extra_whitespace():
    assert truncate_words('one   two   three', 2) == 'one two…'


def test_zero_words():
    assert truncate_words('one two', 0) == '…'

