import pytest

from retry import fetch_with_retry


def test_succeeds_first_time():
    assert fetch_with_retry(lambda: 'ok') == 'ok'


def test_retries_then_succeeds():
    calls = {'n': 0}

    def flaky():
        calls['n'] += 1
        if calls['n'] < 3:
            raise RuntimeError('boom')
        return 'ok'

    assert fetch_with_retry(flaky, retries=3) == 'ok'
    assert calls['n'] == 3


def test_reraises_after_exhausting():
    with pytest.raises(RuntimeError):
        fetch_with_retry(lambda: (_ for _ in ()).throw(RuntimeError('always')), retries=2)
